\"h3_typography_typography\";s:6:\"custom\";s:25:\"h3_typography_font_family\";s:7:\"Poppins\";s:25:\"h3_typography_font_weight\";s:3:\"600\";s:23:\"h3_typography_font_size\";a:3:{s:4:\"unit\";s:2:\"px\";s:4:\"size\";i:22;s:5:\"sizes\";a:0:{}}s:8:\"h3_color\";s:7:\"#2E2E28\";s:24:\"h4_typography_typography\";s:6:\"custom\";s:25:\"h4_typography_font_family\";s:7:\"Poppins\";s:25:\"h4_typography_font_weight\";s:3:\"600\";s:23:\"h4_typography_font_size\";a:3:{s:4:\"unit\";s:2:\"px\";s:4:\"size\";i:18;s:5:\"sizes\";a:0:{}}s:8:\"h4_color\";s:7:\"#2E2E28\";s:24:\"h5_typography_typography\";s:6:\"custom\";s:25:\"h5_typography_font_family\";s:7:\"Poppins\";s:25:\"h5_typography_font_weight\";s:3:\"600\";s:23:\"h5_typography_font_size\";a:3:{s:4:\"unit\";s:2:\"px\";s:4:\"size\";i:15;s:5:\"sizes\";a:0:{}}s:8:\"h5_color\";s:7:\"#2E2E28\";s:24:\"h6_typography_typography\";s:6:\"custom\";s:25:\"h6_typography_font_family\";s:7:\"Poppins\";s:25:\"h6_typography_font_weight\";s:3:\"600\";s:23:\"h6_typography_font_size\";a:3:{s:4:\"unit\";s:2:\"px\";s:4:\"size\";i:13;s:5:\"sizes\";a:0:{}}s:8:\"h6_color\";s:7:\"#2E2E28\";s:10:\"custom_css\";s:14850:\"\n/* ===== Apple-style reveals ===== */\n.ubr-tile{transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s ease}\n.ubr-tile:hover{transform:translateY(-8px);box-shadow:0 22px 50px rgba(46,46,40,.16)}\n.ubr-reveal{opacity:0;transform:translate3d(0,60px,0) scale(.975);transition:opacity .9s cubic-bezier(.22,1,.36,1),transform .9s cubic-bezier(.22,1,.36,1);will-change:transform,opacity}\n.ubr-zoom{opacity:0;transform:scale(.82);transition:opacity .85s cubic-bezier(.22,1,.36,1),transform .85s cubic-bezier(.34,1.56,.64,1);will-change:transform,opacity}\n.ubr-right{opacity:0;transform:translate3d(70px,0,0);transition:opacity .9s cubic-bezier(.22,1,.36,1),transform .9s cubic-bezier(.22,1,.36,1);will-change:transform,opacity}\n.ubr-reveal.is-in,.ubr-zoom.is-in,.ubr-right.is-in{opacity:1;transform:none}\n.ubr-d1.is-in{transition-delay:.10s}.ubr-d2.is-in{transition-delay:.22s}.ubr-d3.is-in{transition-delay:.34s}.ubr-d4.is-in{transition-delay:.46s}\n@media (prefers-reduced-motion:reduce){.ubr-reveal,.ubr-zoom,.ubr-right{opacity:1!important;transform:none!important;transition:none!important}}\n#ubr-progress{position:fixed;top:0;left:0;height:3px;width:0;background:linear-gradient(90deg,#EC5A2A,#1F4D2C);z-index:100000;pointer-events:none;transition:width .08s linear}\n/* ===== responsive helpers ===== */\n.ubr-only-mobile{display:none!important}\n@media (max-width:1024px){.ubr-hide-mobile{display:none!important}.ubr-only-mobile{display:flex!important}}\n/* ===== custom hamburger ===== */\n.ubr-burger{display:flex;flex-direction:column;justify-content:center;gap:5px;width:46px;height:46px;border:0;background:#FAF7EE;border-radius:12px;cursor:pointer;padding:0 11px}\n.ubr-burger span{display:block;height:3px;border-radius:3px;background:#1F4D2C;transition:.3s}\n/* ===== full-screen menu ===== */\n.ubr-menu{position:fixed;inset:0;z-index:100001;background:#FAF7EE;display:flex;flex-direction:column;opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity .4s ease,transform .4s ease,visibility .4s;overflow-y:auto;overscroll-behavior:contain}\n.ubr-menu.is-open{opacity:1;visibility:visible;transform:none}\n.ubr-menu__stamp{position:absolute;right:-70px;bottom:-60px;width:340px;opacity:.06;pointer-events:none;transform:rotate(-8deg)}\n.ubr-menu__top{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid #ECE6D6;position:sticky;top:0;background:#FAF7EE;z-index:2}\n.ubr-menu__top img{width:132px}\n.ubr-menu__close{width:46px;height:46px;border:0;background:#EEF4E3;border-radius:12px;font-size:22px;color:#1F4D2C;cursor:pointer;line-height:1}\n.ubr-menu__links{display:flex;flex-direction:column;padding:14px 22px 4px}\n.ubr-menu__links a{position:relative;font-family:Oswald,sans-serif;font-weight:600;text-transform:uppercase;font-size:30px;letter-spacing:.5px;color:#1F4D2C;text-decoration:none;padding:13px 0;border-bottom:1px solid #ECE6D6;transition:color .2s,padding-left .2s;display:flex;align-items:center;gap:12px}\n.ubr-menu__links a:active,.ubr-menu__links a:hover{color:#EC5A2A;padding-left:8px}\n.ubr-menu__links a::after{content:\"2192\";margin-left:auto;color:#EC5A2A;opacity:.55;font-family:sans-serif}\n.ubr-rewardcard{margin:18px 22px 8px;background:#EC5A2A;border-radius:20px;padding:24px 22px;color:#fff;text-align:center;box-shadow:0 14px 34px rgba(236,90,42,.28)}\n.ubr-rewardcard h3{font-family:Oswald,sans-serif;text-transform:uppercase;font-size:24px;font-weight:600;margin:0 0 4px;color:#fff}\n.ubr-rewardcard p{font-size:13px;margin:0 0 14px;color:#FFE7DC}\n.ubr-rewardcard .cta{display:block;background:#fff;color:#EC5A2A;font-family:Poppins,sans-serif;font-weight:700;text-transform:uppercase;font-size:14px;letter-spacing:.5px;padding:14px;border-radius:50px;text-decoration:none}\n.ubr-rewardcard .signin{display:inline-block;margin-top:12px;color:#fff;font-size:13px;font-weight:600;text-decoration:underline}\n.ubr-menu__order{margin:8px 22px 10px}\n.ubr-menu__order a{display:block;background:#1F4D2C;color:#fff;text-align:center;font-family:Poppins,sans-serif;font-weight:700;text-transform:uppercase;letter-spacing:.5px;font-size:15px;padding:16px;border-radius:50px;text-decoration:none}\n.ubr-menu__social{display:flex;gap:14px;justify-content:center;padding:6px 22px 40px}\n.ubr-menu__social a{width:46px;height:46px;border-radius:50%;background:#1F4D2C;color:#fff;display:flex;align-items:center;justify-content:center;font-size:18px;text-decoration:none}\nbody.ubr-noscroll{overflow:hidden}\n/* ===== mobile sticky action bar ===== */\n.ubr-mobilebar{display:none}\n@media (max-width:1024px){\n  .ubr-mobilebar{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:99990;gap:8px;padding:9px 12px calc(9px + env(safe-area-inset-bottom));background:rgba(255,255,255,.96);backdrop-filter:blur(10px);box-shadow:0 -6px 24px rgba(46,46,40,.14);border-top:1px solid #EEF0E8}\n  .ubr-mobilebar a{flex:1;display:flex;align-items:center;justify-content:center;gap:6px;text-decoration:none;font-family:Poppins,sans-serif;font-weight:600;font-size:13px;border-radius:50px;padding:12px 8px;transition:transform .2s ease}\n  .ubr-mobilebar a:active{transform:scale(.96)}\n  .ubr-mb-primary{flex:1.6!important;background:#EC5A2A;color:#fff!important;box-shadow:0 6px 16px rgba(236,90,42,.35)}\n  .ubr-mb-secondary{background:#EEF4E3;color:#1F4D2C!important}\n  body{padding-bottom:76px!important}\n}\n/* ===== footer two-column on mobile (grid) ===== */\n@media (max-width:767px){\n  .ubr-footer-cols > .e-con-inner{display:grid!important;grid-template-columns:1fr 1fr!important;gap:26px 16px!important;align-items:start!important}\n  .ubr-footer-cols > .e-con-inner > *{width:auto!important;max-width:none!important;flex-basis:auto!important}\n  .ubr-footer-cols > .e-con-inner > .ubr-footer-brand{grid-column:1 / -1!important}\n}\n/* ===== ADV EFFECTS: 3D scroll + scrub + interactive ===== */\n/* 3D depth reveal on zoom elements (works via IntersectionObserver everywhere) */\n.ubr-zoom{opacity:0;transform:perspective(1200px) rotateX(11deg) translateY(38px) scale(.9);transform-origin:50% 100%;transition:opacity .9s cubic-bezier(.22,1,.36,1),transform 1s cubic-bezier(.22,1,.36,1);will-change:transform,opacity}\n.ubr-zoom.is-in{opacity:1;transform:perspective(1200px) rotateX(0) translateY(0) scale(1)}\n/* pointer-tilt cards (fine pointer only) */\n@media (hover:hover) and (pointer:fine){\n  .ubr-tile{transform-style:preserve-3d;transition:transform .35s cubic-bezier(.22,1,.36,1),box-shadow .35s ease}\n  .ubr-tile.ubr-tilting{transition:transform .1s ease-out}\n  .elementor-button{transition:transform .25s cubic-bezier(.34,1.56,.64,1),background-color .3s ease,color .3s ease!important}\n}\n/* scroll-driven scrub for modern browsers (graceful fallback = static) */\n@supports (animation-timeline: view()){\n  @media (prefers-reduced-motion: no-preference){\n    .ubr-scrub{animation:ubrScrub linear both;animation-timeline:view();animation-range:entry 0% cover 60%}\n    @keyframes ubrScrub{from{opacity:.35;transform:translateY(46px) scale(1.05)}to{opacity:1;transform:translateY(0) scale(1)}}\n  }\n}\n@media (prefers-reduced-motion: reduce){\n  .ubr-zoom,.ubr-tile,.elementor-button{transform:none!important;transition:none!important}\n  .ubr-zoom{opacity:1!important}\n}\n\n/* ===== CREATIVE HERO + burger ===== */\n.ubr-hero{position:relative;overflow:hidden;background:radial-gradient(120% 95% at 82% 8%,#DDE8C9 0%,#EEF4E3 42%,#FAF7EE 100%)}\n.ubr-hero::before{content:\"\";position:absolute;width:560px;height:560px;right:-140px;top:-180px;background:radial-gradient(circle,#C6DE9A 0%,transparent 70%);opacity:.55;pointer-events:none;z-index:0}\n.ubr-hero::after{content:\"\";position:absolute;left:-120px;bottom:-160px;width:460px;height:460px;background:radial-gradient(circle,rgba(236,90,42,.16) 0%,transparent 70%);pointer-events:none;z-index:0}\n.ubr-hero > *{position:relative;z-index:1}\n.ubr-rotate{color:#EC5A2A;display:inline-block;transition:opacity .35s cubic-bezier(.22,1,.36,1),transform .35s cubic-bezier(.22,1,.36,1)}\n.ubr-rotate.swap{opacity:0;transform:translateY(14px)}\n.ubr-hero-stage{position:relative;width:min(46vw,460px);aspect-ratio:1/1;margin:24px auto}\n.ubr-hero-ring{position:absolute;inset:-4%;width:108%;height:108%;object-fit:contain;opacity:.09;animation:ubrSpin 44s linear infinite;pointer-events:none}\n.ubr-hero-plate{position:absolute;inset:9%;border-radius:50%;overflow:hidden;background:#fff;box-shadow:0 34px 80px rgba(31,77,44,.28);animation:ubrFloat 6.5s ease-in-out infinite}\n.ubr-hero-plate img{width:100%;height:100%;object-fit:cover;display:block}\n.ubr-float{position:absolute;filter:drop-shadow(0 12px 20px rgba(0,0,0,.20));animation:ubrFloat 5.5s ease-in-out infinite;will-change:transform}\n.ubr-float.f1{top:-3%;right:4%;width:30%;animation-duration:5.5s}\n.ubr-float.f2{bottom:2%;left:-5%;width:34%;animation-duration:7s;animation-delay:.5s}\n.ubr-float.f3{bottom:-4%;right:14%;width:26%;animation-duration:6.2s;animation-delay:.9s}\n@keyframes ubrFloat{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-18px) rotate(3deg)}}\n@keyframes ubrSpin{to{transform:rotate(360deg)}}\n@media (max-width:1024px){.ubr-hero-stage{width:min(80vw,360px)}}\n@media (prefers-reduced-motion:reduce){.ubr-hero-plate,.ubr-float,.ubr-hero-ring{animation:none!important}}\n/* burger as inline element handled in markup; ensure show/hide */\n\n/* ===== POPUP ===== */\n.elementor-popup-modal .ubr-popup{border-radius:22px;overflow:hidden}\n.ubr-popup-form{position:relative}\n.ubr-popup .elementor-field-group input{padding:13px 18px!important}\n@media (max-width:600px){.ubr-popup{flex-direction:column!important}.ubr-popup-img{min-height:150px!important}}\n\n/* ===== Codex design repair 2026-07-16 ===== */\n.ubr-reveal,.ubr-zoom,.ubr-right,.ubr-scrub{opacity:1!important;transform:none!important;animation:none!important;transition:none!important;will-change:auto!important}\n.ubr-parallax{transform:none!important}\n#ubr-progress{display:none!important}\n.ubr-tile{transform:none!important;transition:transform .22s ease,box-shadow .22s ease!important}\n.ubr-tile:hover{transform:translateY(-4px)!important;box-shadow:0 16px 34px rgba(23,75,42,.12)!important}\n.elementor-button{transition:transform .2s ease,background-color .2s ease!important}\n.elementor-button:hover{transform:translateY(-2px)}\n.elementor-element-4337997{padding:10px 28px!important}\n.elementor-element-4337997>.e-con-inner{min-height:62px!important;flex-wrap:nowrap!important;align-items:center!important;gap:28px!important}\n.elementor-element-a7fb712{flex:0 0 auto!important;width:145px!important}\n.elementor-element-a7fb712 img{width:145px!important;height:auto!important}\n.elementor-element-6b1cb46{flex:0 0 auto!important;width:auto!important;min-width:430p