(490, 59, '_elementor_data', '[{\"id\":\"37f6542\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_align_items\":\"center\",\"flex_gap\":{\"unit\":\"px\",\"size\":18,\"column\":\"18\",\"row\":\"18\",\"isLinked\":true},\"background_background\":\"classic\",\"background_color\":\"#EEF4E3\",\"padding\":{\"unit\":\"px\",\"top\":\"72\",\"right\":\"24\",\"bottom\":\"72\",\"left\":\"24\",\"isLinked\":false}},\"elements\":[{\"id\":\"cecad20\",\"elType\":\"widget\",\"widgetType\":\"text-editor\",\"settings\":{\"editor\":\"<p style=\\\"margin:0;text-align:center\\\"><span style=\\\"display:inline-block;background:#FFFFFF;color:#EC5A2A;font-family:Poppins,sans-serif;font-weight:600;font-size:12px;letter-spacing:2px;text-transform:uppercase;padding:7px 18px;border-radius:50px\\\">Help Center<\\/span><\\/p>\",\"_css_classes\":\"ubr-reveal\"},\"elements\":[]},{\"id\":\"397c366\",\"elType\":\"widget\",\"widgetType\":\"heading\",\"settings\":{\"title\":\"Frequently Asked Questions\",\"header_size\":\"h1\",\"align\":\"center\",\"title_color\":\"#1F4D2C\",\"_css_classes\":\"ubr-reveal\"},\"elements\":[]},{\"id\":\"4092332\",\"elType\":\"widget\",\"widgetType\":\"text-editor\",\"settings\":{\"editor\":\"<p style=\\\"text-align:center;color:#2E2E28;font-size:18px\\\">Everything you need to know about ordering, rewards, catering, and more.<\\/p>\",\"_css_classes\":\"ubr-reveal\"},\"elements\":[]}],\"isInner\":false},{\"id\":\"8c90ef2\",\"elType\":\"container\",\"settings\":{\"content_width\":\"boxed\",\"flex_direction\":\"column\",\"flex_align_items\":\"center\",\"max_width\":{\"unit\":\"px\",\"size\":820,\"sizes\":[]},\"flex_gap\":{\"unit\":\"px\",\"size\":20,\"column\":\"20\",\"row\":\"20\",\"isLinked\":true},\"padding\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"24\",\"bottom\":\"50\",\"left\":\"24\",\"isLinked\":false}},\"elements\":[{\"id\":\"73d22fe\",\"elType\":\"widget\",\"widgetType\":\"accordion\",\"settings\":{\"tabs\":[{\"_id\":\"ee5bb9c\",\"tab_title\":\"How do I earn and redeem rewards?\",\"tab_content\":\"<p>Join \\u00dcber Rewards free, then earn 1 point for every $1 you spend \\u2014 order online, scan the app, or give your phone number at checkout. Redeem points for free burritos, bowls, and members-only offers.<\\/p>\"},{\"_id\":\"ee5a735\",\"tab_title\":\"Do you offer delivery?\",\"tab_content\":\"<p>Yes. Every location offers pickup and delivery. Hit Order Now or the Locations page and choose your spot.<\\/p>\"},{\"_id\":\"65a5673\",\"tab_title\":\"Can I cater a large event?\",\"tab_content\":\"<p>Absolutely \\u2014 we cater groups of 10 to 200 with burrito bars, bowl spreads, and taco packs. Request a quote from the Catering page.<\\/p>\"},{\"_id\":\"e157a40\",\"tab_title\":\"Do you have vegan and allergy-friendly options?\",\"tab_content\":\"<p>Yes. We offer vegan picadillo and plenty of plant-based toppings, plus full allergen and nutrition info for every ingredient.<\\/p>\"},{\"_id\":\"c99d705\",\"tab_title\":\"Is there an \\u00dcberrito app?\",\"tab_content\":\"<p>Yes \\u2014 download it on the App Store to order ahead, track points, and unlock app-only offers.<\\/p>\"},{\"_id\":\"d9835c3\",\"tab_title\":\"How do I use a gift card?\",\"tab_content\":\"<p>\\u00dcberrito gift cards work at any location and never expire. Buy or check your balance from the Gift Cards page.<\\/p>\"}],\"title_html_tag\":\"h4\",\"icon_active\":{\"value\":\"fas fa-minus\",\"library\":\"fa-solid\"},\"selected_icon\":{\"value\":\"fas fa-plus\",\"library\":\"fa-solid\"},\"title_color\":\"#1F4D2C\",\"tab_active_color\":\"#EC5A2A\",\"_css_classes\":\"ubr-reveal\"},\"elements\":[]}],\"isInner\":false},{\"id\":\"1b8827c\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_align_items\":\"center\",\"flex_gap\":{\"unit\":\"px\",\"size\":16,\"column\":\"16\",\"row\":\"16\",\"isLinked\":true},\"background_background\":\"classic\",\"background_color\":