eft: 0;\\r\\n    width: 100%;\\r\\n    height: 2px;\\r\\n    z-index: 2;\\r\\n    pointer-events: none;\\r\\n    background-image: repeating-linear-gradient(\\r\\n      90deg,\\r\\n      var(--ub-green) 0 5px,\\r\\n      transparent 5px 11px\\r\\n    );\\r\\n  }\\r\\n\\r\\n  .ub-marquee::before {\\r\\n    top: 7px;\\r\\n  }\\r\\n\\r\\n  .ub-marquee::after {\\r\\n    bottom: 7px;\\r\\n  }\\r\\n\\r\\n  .ub-marquee__track {\\r\\n    display: flex;\\r\\n    width: max-content;\\r\\n    animation: ubMarqueeMove 24s linear infinite;\\r\\n    will-change: transform;\\r\\n  }\\r\\n\\r\\n  .ub-marquee:hover .ub-marquee__track {\\r\\n    animation-play-state: paused;\\r\\n  }\\r\\n\\r\\n  .ub-marquee__group {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    flex-shrink: 0;\\r\\n    gap: 28px;\\r\\n    padding-right: 28px;\\r\\n    font-family: \\\"Oswald\\\",Sans-serif;\\r\\n  }\\r\\n\\r\\n  .ub-marquee__item {\\r\\n    display: inline-flex;\\r\\n    align-items: center;\\r\\n    gap: 28px;\\r\\n    white-space: nowrap;\\r\\n    color: #ffffff;\\r\\n     \\r\\n    font-size: clamp(18px, 1.5vw, 28px);\\r\\n    font-weight: 800;\\r\\n    line-height: 1;\\r\\n    letter-spacing: 0.5px;\\r\\n    text-transform: uppercase;\\r\\n  }\\r\\n\\r\\n  .ub-marquee__dot {\\r\\n    width: 10px;\\r\\n    height: 10px;\\r\\n    flex: 0 0 10px;\\r\\n    border-radius: 50%;\\r\\n    background: var(--ub-green);\\r\\n    box-shadow: 0 0 12px rgba(146, 191, 56, 0.8);\\r\\n  }\\r\\n\\r\\n  .ub-marquee__arrow {\\r\\n    width: 17px;\\r\\n    height: 17px;\\r\\n    flex: 0 0 17px;\\r\\n    border-top: 5px solid var(--ub-green);\\r\\n    border-right: 5px solid var(--ub-green);\\r\\n    transform: rotate(45deg);\\r\\n  }\\r\\n\\r\\n  .ub-marquee__glow {\\r\\n    position: absolute;\\r\\n    top: 50%;\\r\\n    left: 50%;\\r\\n    width: 190px;\\r\\n    height: 16px;\\r\\n    z-index: -1;\\r\\n    pointer-events: none;\\r\\n    transform: translate(-50%, -50%);\\r\\n    background: var(--